INSERT INTO `wp_posts` VALUES (30,1,'2026-07-24 14:54:27','2026-07-24 12:54:27','<!-- wp:acf/tabs-section {\"name\":\"acf/tabs-section\",\"data\":{\"section_title\":\"Features\",\"_section_title\":\"field_6a6355e593ae4\",\"section_description\":\"FeaturesFeatures\",\"_section_description\":\"field_6a63562693ae5\",\"tabs_0_tab_title\":\"Features1\",\"_tabs_0_tab_title\":\"field_6a6357e993ae8\",\"tabs_0_tab_icon\":\"\",\"_tabs_0_tab_icon\":\"field_6a63580e93ae9\",\"tabs_0__content_title\":\"FeaturesFeatures\",\"_tabs_0__content_title\":\"field_6a63585293aea\",\"tabs_0__content_text\":\"FeaturesFeaturesFeaturesFeaturesFeaturesFeatures\",\"_tabs_0__content_text\":\"field_6a63589393aeb\",\"tabs_0_features_0__feature_icon\":\"\",\"_tabs_0_features_0__feature_icon\":\"field_6a63591893aed\",\"tabs_0_features_0_feature_text\":\"\\u003c?php  if (!defined(\'ABSPATH\')) {     exit; }  $section_title = get_field(\'section_title\'); $section_description = get_field(\'section_description\'); $tabs = get_field(\'tabs\');  $block_id = \'tabs-section-\' . ($block[\'id\'] ?? uniqid());  if (!empty($block[\'anchor\'])) {     $block_id = sanitize_title($block[\'anchor\']); }  $class_name = \'tabs-section\';  if (!empty($block[\'className\'])) {     $class_name .= \' \' . sanitize_html_class($block[\'className\']); }  if (empty($tabs)) {     if (is_admin()) {         echo \'\\u003cp\\u003ePlease add at least one tab.\\u003c/p\\u003e\';     }      return; } ?\\u003e  \\u003csection     id=\\u0022\\u003c?php echo esc_attr($block_id); ?\\u003e\\u0022     class=\\u0022\\u003c?php echo esc_attr($class_name); ?\\u003e\\u0022 \\u003e     \\u003cdiv class=\\u0022tabs-section__container\\u0022\\u003e          \\u003c?php if ($section_title || $section_description) : ?\\u003e             \\u003cheader class=\\u0022tabs-section__header\\u0022\\u003e                  \\u003c?php if ($section_title) : ?\\u003e                     \\u003ch2 class=\\u0022tabs-section__title\\u0022\\u003e                         \\u003c?php echo esc_html($section_title); ?\\u003e                     \\u003c/h2\\u003e                 \\u003c?php endif; ?\\u003e                  \\u003c?php if ($section_description) : ?\\u003e                     \\u003cdiv class=\\u0022tabs-section__description\\u0022\\u003e                         \\u003c?php echo wp_kses_post(wpautop($section_description)); ?\\u003e                     \\u003c/div\\u003e                 \\u003c?php endif; ?\\u003e              \\u003c/header\\u003e         \\u003c?php endif; ?\\u003e          \\u003cdiv class=\\u0022tabs-section__navigation-wrapper\\u0022\\u003e             \\u003cdiv                 class=\\u0022tabs-section__navigation\\u0022                 role=\\u0022tablist\\u0022                 aria-label=\\u0022\\u003c?php echo esc_attr($section_title ?: \'Content tabs\'); ?\\u003e\\u0022             \\u003e                 \\u003c?php foreach ($tabs as $index =\\u003e $tab) : ?\\u003e                     \\u003c?php                     $tab_number = $index + 1;                     $tab_id = $block_id . \'-tab-\' . $tab_number;                     $panel_id = $block_id . \'-panel-\' . $tab_number;                     $is_active = $index === 0;                     $tab_icon = $tab[\'tab_icon\'] ?? null;                     ?\\u003e                      \\u003cbutton                         id=\\u0022\\u003c?php echo esc_attr($tab_id); ?\\u003e\\u0022                         class=\\u0022tabs-section__tab\\u003c?php echo $is_active ? \' is-active\' : \'\'; ?\\u003e\\u0022                         type=\\u0022button\\u0022                         role=\\u0022tab\\u0022                         aria-selected=\\u0022\\u003c?php echo $is_active ? \'true\' : \'false\'; ?\\u003e\\u0022                         aria-controls=\\u0022\\u003c?php echo esc_attr($panel_id); ?\\u003e\\u0022                         tabindex=\\u0022\\u003c?php echo $is_active ? \'0\' : \'-1\'; ?\\u003e\\u0022                     \\u003e                         \\u003c?php if (!empty($tab_icon[\'url\'])) : ?\\u003e                             \\u003cimg                                 class=\\u0022tabs-section__tab-icon\\u0022                                 src=\\u0022\\u003c?php echo esc_url($tab_icon[\'url\']); ?\\u003e\\u0022                                 alt=\\u0022\\u003c?php echo esc_attr($tab_icon[\'alt\'] ?? \'\'); ?\\u003e\\u0022                             \\u003e                         \\u003c?php endif; ?\\u003e                          \\u003cspan class=\\u0022tabs-section__tab-title\\u0022\\u003e                             \\u003c?php echo esc_html($tab[\'tab_title\'] ?? \'\'); ?\\u003e                         \\u003c/span\\u003e                     \\u003c/button\\u003e                 \\u003c?php endforeach; ?\\u003e             \\u003c/div\\u003e         \\u003c/div\\u003e          \\u003cdiv class=\\u0022tabs-section__panels\\u0022\\u003e              \\u003c?php foreach ($tabs as $index =\\u003e $tab) : ?\\u003e                 \\u003c?php                 $tab_number = $index + 1;                 $tab_id = $block_id . \'-tab-\' . $tab_number;                 $panel_id = $block_id . \'-panel-\' . $tab_number;                 $is_active = $index === 0;                  $content_title = $tab[\'content_title\'] ?? \'\';                 $content_text = $tab[\'content_text\'] ?? \'\';                 $features = $tab[\'features\'] ?? [];                  $video_type = $tab[\'video_type\'] ?? \'\';                 $video_file = $tab[\'video_file\'] ?? null;                 $video_embed = $tab[\'video_embed\'] ?? \'\';                 $video_poster = $tab[\'video_poster\'] ?? null;                 ?\\u003e                  \\u003cdiv                     id=\\u0022\\u003c?php echo esc_attr($panel_id); ?\\u003e\\u0022                     class=\\u0022tabs-section__panel\\u003c?php echo $is_active ? \' is-active\' : \'\'; ?\\u003e\\u0022                     role=\\u0022tabpanel\\u0022     